<?php
declare(strict_types=1);
session_start(['cookie_httponly'=>true,'cookie_samesite'=>'Strict','cookie_secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off']);
header('X-Frame-Options: DENY');header('X-Content-Type-Options: nosniff');header('Cache-Control: no-store');
$root=is_dir(__DIR__.'/../cvtara_app')?realpath(__DIR__.'/../cvtara_app'):dirname(__DIR__);
$lockFile=$root.'/storage/installed.lock';if(is_file($lockFile)){http_response_code(403);exit('Installation is locked. Sign in at /login.');}
$setupHash=trim((string)@file_get_contents(__DIR__.'/.install-key-hash'));
$setupKey=trim((string)@file_get_contents($root.'/.setup-key'));$errors=[];$success=false;
$_SESSION['install_csrf']??=bin2hex(random_bytes(24));
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
 if(!hash_equals($_SESSION['install_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Refresh the installer and try again.');
 if(!($setupHash&&hash_equals($setupHash,hash('sha256',trim((string)($_POST['setup_key']??'')))))&&(!$setupKey||!hash_equals($setupKey,trim((string)($_POST['setup_key']??'')))))throw new RuntimeException('Use the installation key included in your private installation notes.');

 if(is_file(__DIR__.'/.cvtara-payload.zip')){
  if(!class_exists('ZipArchive'))throw new RuntimeException('Enable the ZIP extension in Hostinger PHP settings, then retry.');
  $target=dirname(__DIR__).'/cvtara_app';$extractLock=fopen(__DIR__.'/.extract.lock','c');if(!$extractLock||!flock($extractLock,LOCK_EX|LOCK_NB))throw new RuntimeException('Setup is already opening the application. Retry shortly.');
  if(!is_dir($target)){if(!is_writable(dirname(__DIR__)))throw new RuntimeException('Hostinger must allow the private app folder beside public_html. Ask hosting support to allow this folder.');$tmp=dirname(__DIR__).'/.cvtara-unpack-'.bin2hex(random_bytes(6));mkdir($tmp,0700);$zip=new ZipArchive();if($zip->open(__DIR__.'/.cvtara-payload.zip')!==true)throw new RuntimeException('The upload package is incomplete. Upload and extract it again.');for($i=0;$i<$zip->numFiles;$i++){$n=$zip->getNameIndex($i);if(str_contains($n,'..')||str_starts_with($n,'/')||str_contains($n,'\\'))throw new RuntimeException('Invalid application archive.');}$zip->extractTo($tmp);$zip->close();if(!is_file($tmp.'/artisan')||!rename($tmp,$target))throw new RuntimeException('Could not create the private application folder.');}
  $root=realpath($target);$lockFile=$root.'/storage/installed.lock';flock($extractLock,LOCK_UN);fclose($extractLock);
 }
 if(PHP_VERSION_ID<80300)throw new RuntimeException('Choose PHP 8.3 or newer in hPanel.');foreach(['pdo_mysql','mbstring','openssl','fileinfo','curl','xml','zip','gd'] as $ext)if(!extension_loaded($ext))throw new RuntimeException('Enable PHP extension: '.$ext);
 $url=rtrim(trim($_POST['url']??''),'/');$parts=parse_url($url);if(($parts['scheme']??'')!=='https'||empty($parts['host'])||isset($parts['user'])||isset($parts['query'])||isset($parts['fragment'])||!empty($parts['path']))throw new RuntimeException('Enter your HTTPS domain or subdomain without a path. Enable SSL first.');
 $email=strtolower(trim($_POST['email']??''));$name=trim($_POST['name']??'');$password=$_POST['password']??'';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||!$name||strlen($name)>120||strlen($password)<12||strlen($password)>200)throw new RuntimeException('Use a valid owner email, name and a password of at least 12 characters.');
 $host=trim($_POST['db_host']??'localhost');$db=trim($_POST['db_name']??'');$user=trim($_POST['db_user']??'');$pass=$_POST['db_password']??'';if(!preg_match('/^[a-zA-Z0-9_.-]+$/',$host)||!preg_match('/^[a-zA-Z0-9_]+$/',$db)||!preg_match('/^[a-zA-Z0-9_]+$/',$user))throw new RuntimeException('Check your database host, name and username.');
 $pdo=new PDO("mysql:host=$host;dbname=$db;charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
 $existing=$pdo->query("SHOW TABLES LIKE 'users'")->fetchColumn();if($existing&&(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn()>0)throw new RuntimeException('This database already contains accounts. Use an empty database; restore existing sites from their original application key and backup.');
 $guard=fopen($root.'/storage/installing.lock','c');if(!$guard||!flock($guard,LOCK_EX|LOCK_NB))throw new RuntimeException('Another installation is running.');if(is_file($lockFile))throw new RuntimeException('Installation is already complete.');
 $quote=function($s){if(preg_match('/[\r\n\x00]/',$s))throw new RuntimeException('Configuration cannot contain line breaks.');return '"'.str_replace(['\\','"','$'],['\\\\','\\"','\\$'],$s).'"';};
