 }catch(Throwable $e){$errors[]=$e instanceof PDOException?'Could not connect to the database. Check the exact hPanel credentials.':$e->getMessage();}
}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Install CVTara</title><style>body{font:16px/1.5 Arial;background:#edf3fc;color:#17304c}main{max-width:680px;margin:4vh auto;background:white;padding:32px;border-radius:18px}label{display:block;margin:16px 0}input{display:block;padding:11px;width:100%;box-sizing:border-box;font:inherit;border:1px solid #a9bbcf;border-radius:8px}button{padding:14px 20px;background:#1557d2;color:white;border:0;border-radius:8px;font:inherit}.error{color:#aa2030}</style><link rel="icon" href="/favicon.ico" sizes="any"><link rel="icon" type="image/svg+xml" href="/assets/brand/cvtara-mark.svg"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><meta name="theme-color" content="#214ed3"></head><body><main><img src="/assets/brand/cvtara-logo.svg" width="240" height="64" alt="CVTara"><h1>Install CVTara</h1><?php if($success):?><h2>Installation complete</h2><p>Delete install.php from public_html. Sign in and open Guided setup. It will help you connect email, payments and phone verification, and show the remaining account steps.</p><a href="/login">Continue to guided setup</a><?php else:?><p>Use an empty MySQL database and PHP 8.3+. Your application folder must be outside public_html. This setup creates the owner account and locks itself when complete.</p><?php foreach($errors as $err):?><p class="error" role="alert"><?=h($err)?></p><?php endforeach?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['install_csrf'])?>"><?php foreach(['setup_key'=>'Installation key','url'=>'HTTPS domain (https://yourdomain.com)','db_host'=>'Database host','db_name'=>'Database name','db_user'=>'Database username','db_password'=>'Database password','name'=>'Owner full name','email'=>'Owner email','password'=>'Owner password (12+ characters)'] as $key=>$label):?><label><?=h($label)?><input name="<?=$key?>" type="<?=str_contains($key,'password')||$key==='setup_key'?'password':($key==='email'?'email':'text')?>" required value="<?=h($key==='db_host'?'localhost':($key==='url'?'https://'.preg_replace('/[^a-zA-Z0-9.-]/','',$_SERVER['HTTP_HOST']??''):''))?>" autocomplete="off"></label><?php endforeach?><button>Install and create owner</button></form><?php endif?></main></body></html>
